{
  "metadata": {
    "worldName": "太极八荒",
    "version": "1.0",
    "type": "cultivation_fantasy_world",
    "language": "zh-CN",
    "source": "用户提供的世界观设定，结构化整理"
  },
  "corePhilosophy": {
    "origin": "世界源于混沌（无极），分化出阴阳二气（太极），阴阳交泰、衍生五行，进而演化出八荒寰宇",
    "cultivation": "修仙之道，乃逆天而行，窃阴阳、夺造化，以求超脱八荒束缚，证道永恒",
    "nature": "此界光暗交织，既有仙气缥缈的圣地，亦有弱肉强食、污秽血腥的泥沼"
  },
  "timeline": [
    {
      "era": "混沌初开",
      "alias": "无极纪元",
      "description": "虚空爆炸，阴阳分离，清浊升降，八荒大陆定型，先天神魔自法则中诞生，居于九天九幽"
    },
    {
      "era": "太古纪元",
      "alias": "神魔纪元",
      "description": "神魔统治天地，执掌法则权柄，视万物为刍狗。蛮荒巨兽、先天精怪横行八荒"
    },
    {
      "era": "上古纪元",
      "alias": "百族纪元",
      "description": "百族（人、妖、巫、灵族、龙族等）逐渐诞生灵智，崛起于微末。爆发反抗神魔统治的'绝地天通'之战，导致天地桥梁崩毁，神魔或隐退、或陨落、或被封印，其传承散落天地。此后百族为争夺生存空间与资源，征伐不断"
    },
    {
      "era": "中古纪元",
      "alias": "道统纪元",
      "description": "人族凭借卓越的悟性和繁衍能力大兴，系统性地确立修仙体系，宗门、王朝开始林立。与妖族爆发持续万年的大战，最终划定势力范围。期间正、魔、佛、妖等道统概念明晰，爆发多次席卷八荒的大战"
    },
    {
      "era": "近古纪元",
      "alias": "稳定纪元",
      "description": "八荒格局相对稳定，各势力维持着微妙的平衡。跨荒交流因传送阵技术的改进而增多，探索上古遗迹秘境成为高阶修士寻求机缘的主流。然暗流涌动，异界威胁、资源枯竭、内部倾轧等危机隐现"
    }
  ],
  "worldStructure": {
    "lowerRealm": {
      "name": "下界（凡尘八荒）",
      "description": "修仙文明的根基所在，由八块巨大无比、被无尽混沌海与虚空风暴隔开的主大陆，以及环绕它们的无数星辰、浮空岛屿、秘境碎片构成。灵气浓度不均，是亿万生灵诞生、繁衍及修仙之路的起点",
      "continents": [
        {
          "id": "dongji",
          "name": "东极青木荒",
          "element": "木",
          "geography": "无边林海覆盖，巨木参天，植被繁茂异常，多有天然形成的树屋城市与空中藤桥。河流湖泊如翡翠般点缀其间",
          "naturalWonders": [
            "生命之泉",
            "远古树心",
            "迷雾森林",
            "妖精花谷"
          ],
          "dominantForces": [
            "万兽山",
            "东方世家"
          ],
          "resources": [
            "灵木",
            "灵草",
            "灵药",
            "木系灵石",
            "妖丹"
          ]
        },
        {
          "id": "nanming",
          "name": "南溟离火荒",
          "element": "火",
          "geography": "火山地貌广布，熔岩河纵横交错，拥有广阔的炎漠与赤色岩石山脉。天空常呈赤红色，时有火雨流星",
          "naturalWonders": [
            "不死火山",
            "熔岩血海",
            "焚风谷",
            "赤晶石林"
          ],
          "dominantForces": [
            "天妖凰庭",
            "血魔殿（潜伏于地下熔岩网络）"
          ],
          "resources": [
            "火系灵石",
            "各种灵火",
            "炎铁",
            "火铜",
            "阳属性矿石"
          ]
        },
        {
          "id": "xisha",
          "name": "西煞庚金荒",
          "element": "金",
          "geography": "戈壁与裸露的矿山是主旋律，大地呈现金属色泽，锐利的金风常年呼啸。山川陡峭如剑，富含矿藏",
          "naturalWonders": [
            "剑刃山脉",
            "裂金大峡谷",
            "磁暴平原",
            "白金沙漠"
          ],
          "dominantForces": [
            "蜀山剑宗",
            "南宫世家"
          ],
          "resources": [
            "各类金属灵矿",
            "金系灵石",
            "剑胚石",
            "锐金之气"
          ]
        },
        {
          "id": "beiming",
          "name": "北冥玄水荒",
          "element": "水/冰",
          "geography": "被无尽冰原与浩瀚寒海覆盖，冰川巍峨，浮冰万里。深海之下压力巨大，有发光水母森林与海沟城市",
          "naturalWonders": [
            "无尽冰壁",
            "归墟之眼",
            "极光天幕",
            "深渊海沟"
          ],
          "dominantForces": [
            "龙宫",
            "北极冰风王朝",
            "须弥山"
          ],
          "resources": [
            "水系/冰系灵石",
            "万年玄冰",
            "深海玉髓",
            "水魂珠",
            "寒铁"
          ]
        },
        {
          "id": "zhongtu",
          "name": "中土黄帝荒",
          "element": "土（五行均衡）",
          "geography": "山河壮丽，平原广阔，气候宜人，五行灵气最为均衡。江河网络密布，龙脉之地众多，人族城市繁华鼎盛",
          "naturalWonders": [
            "不周山（传说连接天地的残骸）",
            "昆仑山脉（万山之祖）",
            "黄河祖脉",
            "王屋洞天"
          ],
          "dominantForces": [
            "太上道一宗",
            "大夏仙朝",
            "轩辕世家"
          ],
          "resources": [
            "综合类资源最丰富",
            "五行均衡的灵石",
            "灵谷",
            "灵茶",
            "气运相关的宝物"
          ]
        },
        {
          "id": "xunfeng",
          "name": "巽风苍云荒",
          "element": "风/雷",
          "geography": "高原地形，接天连地，永不停息的飓风带环绕大陆。多有浮空山屿与悬空河流，雷暴天气频繁",
          "naturalWonders": [
            "九天罡风层",
            "雷暴云海",
            "悬空山链",
            "风眼之湖"
          ],
          "dominantForces": [
            "巡天盟（重要总部及多处据点）",
            "风雷阁",
            "云渺宗"
          ],
          "resources": [
            "风属性/雷属性灵石",
            "天青石",
            "风雷木",
            "浮空石"
          ]
        },
        {
          "id": "genshan",
          "name": "艮山厚土荒",
          "element": "山/土",
          "geography": "连绵无尽的十万大山，地下洞穴网络错综复杂，遍布深渊、裂谷。地磁异常，土石系灵气厚重沉凝",
          "naturalWonders": [
            "不破地脉（主灵脉）",
            "千窟洞",
            "巨石迷宫",
            "地心熔湖"
          ],
          "dominantForces": [
            "天衍器宗",
            "磐石门",
            "地底妖族"
          ],
          "resources": [
            "土系灵石",
            "各类珍稀矿石",
            "地心火莲",
            "戊土精粹"
          ]
        },
        {
          "id": "duize",
          "name": "兑泽幽沼荒",
          "element": "泽/暗",
          "geography": "广阔的沼泽湿地弥漫着永不消散的毒瘴，阴湿腐朽。多毒虫异草、扭曲林木，光线昏暗，暗影能量浓郁",
          "naturalWonders": [
            "腐烂泥潭",
            "鬼哭林",
            "毒瘴核心",
            "阴影裂隙"
          ],
          "dominantForces": [
            "合欢宗（总坛）",
            "幽冥教（分舵）",
            "五毒教",
            "无涯黑市（最大据点）",
            "忘川渡（重要基地）"
          ],
          "resources": [
            "毒物",
            "阴性灵草",
            "暗影石",
            "幽冥材料",
            "血魂晶（黑暗特产）"
          ]
        }
      ]
    },
    "upperRealm": {
      "name": "上界（仙界/天界）",
      "description": "位于更高维度的空间，是下界修士飞升后的目的地。灵气转化为更高层次的仙灵之气，浓度远胜下界，天地法则更为清晰稳固。传闻分为'九重天'，层级越高，仙气越浓郁精纯，居住者的实力与地位也越高。并非绝对的乐土，同样存在庞大的仙界势力、资源争夺与道统纷争"
    },
    "secretRealms": {
      "name": "附属/秘境空间",
      "description": "依附于主世界存在的小型、半独立或不稳定空间。成因多样：上古大能开辟的洞府、大战打碎的空间碎片、自然形成的元素奇境、连接异次元的时空裂缝、大型阵法构建的亚空间等。这些秘境通常蕴藏着外界罕见的天材地宝、上古传承或失落的功法，但也往往伴随着巨大的空间风暴、守护凶兽、绝杀阵法等未知危险，是修士们寻求机缘与冒险的重要场所"
    },
    "otherRealms": {
      "name": "异界/魔域",
      "description": "与太极八荒主世界部分接壤或通过不稳定时空通道连接的其他维度世界。其物理规则、能量体系可能与太极八荒迥异，可能由深渊恶魔、域外天魔、虚空异族、或修炼截然不同力量体系的生物主导。它们通常是外部冲突和入侵的来源，其能量属性常与灵气相冲，是八荒众生需要共同警惕的威胁"
    }
  },
  "economicSystem": {
    "currencies": [
      {
        "name": "灵石",
        "type": "primary",
        "description": "天地灵气凝聚而成的矿石，是修仙界的基础硬通货。既是货币，也可直接用于修炼、恢复法力、驱动阵法法器",
        "grades": [
          {
            "grade": "下品灵石",
            "quality": "杂质较多，灵气含量一般，呈浑浊的灰白色",
            "exchangeRateToNext": "100下品=1中品"
          },
          {
            "grade": "中品灵石",
            "quality": "杂质较少，灵气纯净度高，呈半透明状，带有属性微光",
            "exchangeRateToNext": "100中品=1上品",
            "usedBy": "筑基期以上修士"
          },
          {
            "grade": "上品灵石",
            "quality": "杂质极少，灵气精纯浓郁，晶莹剔透，属性光芒清晰",
            "exchangeRateToNext": "100上品=1极品（理论值）",
            "usedBy": "金丹期及以上修士"
          },
          {
            "grade": "极品灵石",
            "quality": "近乎无杂质，灵气磅礴如海，光华内敛，触之温润",
            "exchangeRateToNext": "无固定比例，通常以物易物",
            "usage": [
              "渡劫",
              "顶级大阵",
              "大能交易"
            ]
          }
        ]
      },
      {
        "name": "灵玉币",
        "type": "secondary",
        "description": "由修仙王朝或大型商会统一铸造，掺有少量灵粉的玉质钱币",
        "exchangeRate": "约100灵玉币≈1下品灵石（地区浮动）",
        "usedBy": "凡人与低阶炼气期修士"
      },
      {
        "name": "仙玉",
        "type": "upperRealm",
        "description": "仙界流通的基础货币，蕴含更高层次的仙灵之气",
        "exchangeRate": "1仙玉≈10000极品灵石（粗略估算）",
        "rarity": "下界极难寻觅",
        "usedBy": "大乘期、渡劫期修士或顶级势力"
      },
      {
        "name": "贡献点",
        "type": "internal",
        "description": "宗门、世家或大型组织内部流通的积分体系",
        "obtainMethod": [
          "完成任务",
          "上交资源"
        ],
        "usage": [
          "兑换功法",
          "丹药",
          "法器",
          "进入修炼秘境"
        ]
      },
      {
        "name": "以物易物",
        "type": "barter",
        "description": "高阶修士间或价值难以用灵石衡量时普遍采用的交易方式",
        "determinants": [
          "稀有度",
          "功效",
          "需求度"
        ]
      }
    ],
    "industries": [
      {
        "name": "灵植农业",
        "products": [
          "灵谷",
          "灵药",
          "灵茶"
        ],
        "importance": "低阶修士和凡人的重要生计，炼丹业基础"
      },
      {
        "name": "矿产采掘",
        "products": [
          "灵石矿脉",
          "各属性灵矿"
        ],
        "importance": "各大势力的命脉和争夺焦点"
      },
      {
        "name": "妖兽狩猎",
        "products": [
          "内丹",
          "皮毛",
          "骨骼",
          "精血"
        ],
        "importance": "高风险高收益，材料来源"
      },
      {
        "name": "炼丹业",
        "products": [
          "各品级丹药"
        ],
        "importance": "核心产业，利润丰厚"
      },
      {
        "name": "炼器业",
        "products": [
          "法器",
          "法宝"
        ],
        "importance": "技术门槛高，高端产业"
      },
      {
        "name": "制符/阵法",
        "products": [
          "符箓",
          "阵法"
        ],
        "importance": "知识密集型产业"
      }
    ],
    "tradeSystems": [
      {
        "name": "坊市",
        "types": [
          "固定坊市（宗门/城市）",
          "临时坊市（秘境开启前集结地）"
        ],
        "function": "修士聚集交易的城市或集镇"
      },
      {
        "name": "拍卖行",
        "operator": [
          "万象天阁",
          "顶级宗门"
        ],
        "function": "交易珍贵、稀有物品"
      },
      {
        "name": "商会组织",
        "examples": [
          "万象天阁"
        ],
        "influence": "跨地域资源流通与价格调控"
      },
      {
        "name": "黑市",
        "example": "无涯黑市",
        "function": "交易明面上禁止的物品"
      }
    ],
    "economicEntities": [
      {
        "type": "修仙宗门",
        "profile": "控制大量资源产地和人才，产业齐全，经济实力雄厚，是高端资源的主要生产者和消费者"
      },
      {
        "type": "修仙世家",
        "profile": "往往专注于特定产业，与宗门结盟形成利益网络"
      },
      {
        "type": "修仙王朝",
        "profile": "管理凡人世界与低阶修士，征税与组织大规模生产，拥有修士军团"
      },
      {
        "type": "散修与联盟",
        "profile": "从事狩猎、探险、采矿等高风险业务，供应基础资源"
      },
      {
        "type": "凡人社会",
        "profile": "提供基础人力、农产品与手工业品，修仙体系的基石"
      },
      {
        "type": "黑暗势力",
        "profile": "通过掠夺、贩卖等非法手段获取与流通资源"
      }
    ]
  },
  "cultivationSystem": {
    "humanPath": {
      "realms": [
        {
          "majorRealm": "基础境（褪凡）",
          "stages": [
            {
              "name": "练气期",
              "description": "引气入体，淬炼经脉，凝聚真气，初步超脱凡人范畴，可修习运用低阶术法",
              "subStages": {
                "初期": {
                  "criteria": "引入第一缕灵气入体，贯通经脉，丹田成气感"
                },
                "中期": {
                  "criteria": "小周天稳定运行，气海初成，真气呈雾状，低阶术法熟练"
                },
                "后期": {
                  "criteria": "大周天流畅，雾状真气有液化迹象，可初御低阶法器"
                },
                "圆满": {
                  "criteria": "丹田充盈，雾气欲滴，神识初生可内视，准备筑基"
                }
              },
              "evaluationStandards": [
                "丹田气海大小与充盈度",
                "真气精纯度",
                "周天运行速度与通畅度",
                "术法威力与持久力"
              ],
              "lifespan": "约100-120岁"
            },
            {
              "name": "筑基期",
              "description": "真气化液，筑就道基，脱胎换骨，真正踏入修仙之门，可御器飞行",
              "subStages": {
                "初期": {
                  "criteria": "凝成第一滴真元液，道基雏形显现，体质首次全面强化"
                },
                "中期": {
                  "criteria": "真元液增多，道基稳固，外放微弱护体灵光"
                },
                "后期": {
                  "criteria": "真元充盈丹田，御器飞行速度与灵活性大增"
                },
                "圆满": {
                  "criteria": "真元凝练至极，道基完美稳固，神识增强，备凝金丹"
                }
              },
              "foundationGrades": [
                {
                  "grade": "下品道基",
                  "quality": "斑驳不稳"
                },
                {
                  "grade": "中品道基",
                  "quality": "稳固寻常"
                },
                {
                  "grade": "上品道基",
                  "quality": "坚实宽阔"
                },
                {
                  "grade": "完美道基",
                  "quality": "无瑕圆润"
                }
              ],
              "lifespan": "约200-250岁"
            },
            {
              "name": "金丹期",
              "description": "液凝成丹，能量核心初成，寿元大增，神通初显",
              "subStages": {
                "初期": {
                  "criteria": "极度压缩真元成固态金丹（龙眼大小），需温养稳固"
                },
                "中期": {
                  "criteria": "金丹稳固，法力化，神识增强可覆数里，本命法宝孕养"
                },
                "后期": {
                  "criteria": "法力澎湃，神识初干涉现实，调动天地灵气显著增强"
                },
                "圆满": {
