        "name": "万象天阁",
        "type": "跨荒商业组织",
        "tenet": "万物可易，万象更新",
        "traits": "巨型商会，信誉极高，举办大型拍卖会，发布《万象宝录》，背景深不可测，疑与仙界或散仙相关",
        "notableFigures": [
          "总阁主（不详）",
          "各荒大掌柜"
        ]
      },
      {
        "name": "天机楼",
        "type": "情报组织",
        "tenet": "天机可测，万物皆明",
        "traits": "贩卖情报，制定权威榜单（天骄榜、龙凤榜、潜龙榜、神兵榜、异火榜、宗门实力榜），网络无孔不入，价格昂贵",
        "notableFigures": [
          "天机子（不详）",
          "各地负责人"
        ]
      },
      {
        "name": "巡天盟",
        "type": "散修联盟",
        "tenet": "互帮互助，共求仙道",
        "traits": "为散修谋利，抗衡大宗门与魔道，结构松散，总部巽风苍云荒悬空城，常组织遗迹探索",
        "notableFigures": [
          "盟主雷啸天（合体初期）",
          "若干副盟主"
        ]
      }
