        "name": "影阁",
        "type": "杀手组织",
        "tenet": "阴影之下，死亡相随。拿人钱财，与人消灾",
        "traits": "最神秘杀手组织，几无失手（超纲不接），成员代号制，价格极高，疑有空间刺杀术",
        "notableFigures": [
          "影主（不详）",
          "十大影杀使（不详）"
        ]
      },
