{
  "metadata": {
    "name": "洛倾城",
    "title": "天香圣宫圣主",
    "status": "圣地之主",
    "affiliation": "天香圣宫",
    "version": "1.0",
    "language": "zh-CN",
    "type": "character_profile"
  },
  "appearance": {
    "gender": "female",
    "age": "三千余岁，外貌二十五六岁",
    "height_cm": 173,
    "weight_kg": 56,
    "measurements_cm": {
      "bust": 101,
      "waist": 60,
      "hips": 99,
      "cup": "H"
    },
    "skin": "雪白细腻，光滑如玉，带有淡淡冷香",
    "hair": "漆黑长发，垂落腰间，常以金簪固定，点缀宝石与丝缎",
    "eyes": "金棕色眼瞳，含着媚意与威势，笑时犹如摄魂",
    "face": "瓜子脸，眉目修长，唇色殷红，举止间流露帝王般妖冶尊贵",
    "distinctFeatures": [
      "眉心花钿，呈现深蓝妖花形状，象征圣地传承",
      "常执长烟杆，烟雾氤氲，带有催情与迷幻之效",
      "气息常伴幽香，沁人心神"
    ]
  },
  "clothing": {
    "headAccessories": [
      "金饰凤冠：繁复雕琢，点缀蓝色流苏与宝石",
      "长流苏耳饰：随动作轻摇，散发悦耳清脆声"
    ],
    "upperBody": {
      "outerLayer": "宝蓝色贴身宫装，裁剪贴合，开胸极深，勾勒胸线曲线，辅以鎏金花纹",
      "innerLayer": "黑色轻纱打底，若隐若现，增加层次与诱惑",
      "underwear": "镶金丝边的深蓝内衣，蕾丝纹饰环绕，支撑胸部曲线"
    },
    "waist": "镶嵌蓝宝石的宽腰封，暗含符文，既是装饰亦是护身法器",
    "lowerBody": {
      "pantsOrSkirt": "高开衩旗袍式裙摆，宝蓝织锦，裙摆两侧以金扣固定，行动间若隐若现",
      "underwear": "黑色蕾丝内裤，镶蓝色丝线，配合开衩裙摆若隐若现",
      "stockings": "黑色丝滑长筒丝袜，紧贴双腿，勾勒修长与圆润"
    },
    "cloakOrShawl": "雪白披帛，质地轻柔，覆盖肩部与手臂，行走时如云雾般流动",
    "footwear": "赤足或金丝刺绣宫鞋，赤足时以黑色薄丝足衣包裹"
  },
  "bodyPosture": {
    "description": "姿态慵懒而高贵，常斜倚坐姿，举止间带有不容忽视的威压与魅惑。",
